        static void SchemeLanguage(string language, string[] keys, string values)
        {
            var words = values.Split('|');
            for (int i = 0; i < keys.Length; i++) Add(language, "schemes." + keys[i], words[i]);
            string[] names = { "方案切换", "Switch schemes", "設定切替", "설정 전환", "Переключение схем", "方案切換", "Changer de schéma", "Schema wechseln", "Cambiar esquema", "Trocar esquema", "Cambia schema", "เปลี่ยนชุดปุ่ม", "Chuyển cấu hình", "Mudar esquema", "Cambiar esquema" };
            Add(language, "schemes.group", names[System.Array.IndexOf(Languages, language)]);
        }
